package ro.leo.visual;
import ro.leo.i18n.L;
import android.content.*;
import android.os.Bundle;
import java.util.*;
public final class PersonalizationActivity extends LeoActivity {
    protected void onCreate(Bundle state){super.onCreate(state);if(getIntent().getBooleanExtra("order",false))order(0);else home();}
    private void home(){list(L.t("Personalizare"),Arrays.asList(L.t("Ordinea aplicațiilor"),L.t("Scurtături pe Home"),L.t("Dimensiunea textului"),L.t("Notificări pe ecranul blocat"),L.t("Fundaluri și teme"),L.t("Profiluri sonore"),L.t("Favorite și apelare rapidă"),L.t("Home · ceas și informații"),L.t("Accente și teme pe aplicații"),L.t("Colecții vizuale complete"),L.t("Ordinea și selecția cardurilor Home"),"Language / Limbă",L.t("Profilurile mele"),L.t("Centrul de aplicații")),0,new Choice(){public void pick(int i){if(i==13)startActivity(new Intent(PersonalizationActivity.this,AppControlActivity.class));else if(i==12)startActivity(new Intent(PersonalizationActivity.this,VisualProfilesActivity.class));else if(i==11)startActivity(new Intent(PersonalizationActivity.this,LanguageSettingsActivity.class));else if(i==10)startActivity(new Intent(PersonalizationActivity.this,HomeLayoutActivity.class));else if(i==9)startActivity(new Intent(PersonalizationActivity.this,ThemePacksActivity.class));else if(i==8)startActivity(new Intent(PersonalizationActivity.this,StyleSettingsActivity.class));else if(i==0)order(0);else if(i==1)shortcuts();else if(i==2)options("Text",new String[]{"Normal",L.t("Mai mare")},new Choice(){public void pick(int n){getSharedPreferences("appearance",0).edit().putBoolean("large-text",n==1).apply();home();}});else if(i==3)previews();else if(i==4)startActivity(new Intent(PersonalizationActivity.this,WallpaperActivity.class));else if(i==5)SoundProfiles.select(PersonalizationActivity.this,new Runnable(){public void run(){home();}});else if(i==7)homeLayout();else startActivity(new Intent(PersonalizationActivity.this,SpeedDialActivity.class));}},"",null);}
    private void homeLayout(){final android.content.SharedPreferences p=getSharedPreferences("appearance",0);final String[] keys={"home-compact","home-sims","home-unread","home-dbm","home-weather","home-alarm","home-music","lock-info","lock-media"};final String[] labels={L.t("Ceas compact"),L.t("Starea ambelor SIM-uri"),L.t("Puncte pentru notificări"),L.t("Semnal în dBm"),L.t("Card Meteo"),L.t("Card Alarmă"),L.t("Card Muzică / FM"),L.t("Blocare · Meteo și alarmă"),L.t("Blocare · card media")};ArrayList<String> rows=new ArrayList<String>();for(int i=0;i<keys.length;i++)rows.add(labels[i]+" · "+(p.getBoolean(keys[i],i!=0)?L.t("Da"):L.t("Nu")));list(L.t("Aspect Home"),rows,0,new Choice(){public void pick(int i){p.edit().putBoolean(keys[i],!p.getBoolean(keys[i],i!=0)).apply();homeLayout();}},L.t("Resetează"),new Runnable(){public void run(){android.content.SharedPreferences.Editor e=p.edit();for(String key:keys)e.remove(key);e.apply();homeLayout();}});back=new Runnable(){public void run(){home();}};}
    private void order(int selected){final int[] ids=AppCatalog.menuOrder(this,0);ArrayList<String> labels=new ArrayList<String>();for(int id:ids)labels.add(AppCatalog.NAMES[id]);list(L.t("Ordinea aplicațiilor"),labels,selected,new Choice(){public void pick(final int at){options(AppCatalog.NAMES[ids[at]],new String[]{L.t("Mută mai sus"),L.t("Mută mai jos"),L.t("Mută la început"),L.t("Înapoi")},new Choice(){public void pick(int action){int target=action==0?Math.max(0,at-1):action==1?Math.min(ids.length-1,at+1):action==2?0:at;int id=ids[at];if(target<at)System.arraycopy(ids,target,ids,target+1,at-target);else if(target>at)System.arraycopy(ids,at+1,ids,at,target-at);ids[target]=id;AppCatalog.save(PersonalizationActivity.this,ids);order(target);}});}},L.t("Resetează"),new Runnable(){public void run(){options(L.t("Resetezi ordinea?"),new String[]{L.t("Păstrează"),L.t("Resetează")},new Choice(){public void pick(int i){if(i==1){getSharedPreferences("appearance",0).edit().remove("app-order").apply();order(0);}}});}});back=new Runnable(){public void run(){home();}};}
    private void shortcuts(){int[] ids=AppCatalog.shortcuts(this);ArrayList<String> labels=new ArrayList<String>();for(int i=0;i<ids.length;i++)labels.add((i+1)+" · "+AppCatalog.NAMES[ids[i]]);list(L.t("Scurtături Home"),labels,0,new Choice(){public void pick(final int slot){list(L.t("Alege aplicația"),Arrays.asList(AppCatalog.NAMES),0,new Choice(){public void pick(int id){getSharedPreferences("appearance",0).edit().putInt("shortcut"+slot,id).apply();shortcuts();}},"",null);back=new Runnable(){public void run(){shortcuts();}};}},"",null);back=new Runnable(){public void run(){home();}};}
    private void previews(){list(L.t("Notificări la blocare"),Arrays.asList(L.t("Ascunde previzualizările"),L.t("Afișează titlurile"),L.t("Afișează titlul și textul")),getSharedPreferences("appearance",0).getInt("lock-preview",0),new Choice(){public void pick(final int mode){if(mode==2)options(L.t("Text vizibil fără deblocare"),new String[]{L.t("Anulează"),L.t("Permite previzualizarea")},new Choice(){public void pick(int yes){if(yes==1)savePreview(mode);}});else savePreview(mode);}},"",null);back=new Runnable(){public void run(){home();}};}
    private void savePreview(int mode){getSharedPreferences("appearance",0).edit().putInt("lock-preview",mode).apply();notice(L.t("Preferința notificărilor salvată"));home();}
}
